import pandas as pd, numpy as np, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv'); cols=['canopy_cover','soil_moisture','elevation_m','road_dist_km','leaf_litter','temperature_c','slope_deg','nitrate','grazing_index','rainfall_mm'];
for c in cols:
 d=x[['species_richness','region',c]].dropna(); m=smf.ols(f'species_richness ~ {c} + C(region)',d).fit(); print(c, round(m.params[c],3),round(m.pvalues[c],5),round(m.rsquared,3))

